# Run from the package root after 52, 52b, 52c, 52d, 55, 55b, 57, 58 and 59:  Rscript data-raw/qa/61_fidelity_section.R
# Writes the section "What is and is not done to the source data" of data-raw/known_issues.md (between <!-- fidelity:start --> and <!-- fidelity:end -->). Every number is read from the saved results of the QA scripts.
suppressMessages({library(dplyr)}); source("data-raw/qa/helpers.R"); f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x); need <- function(f) { if (!file.exists(qa_out(f))) stop("missing ", qa_out(f), ": run the QA scripts first", call. = FALSE); readRDS(qa_out(f)) }
au <- need("audit_counts.rds"); ab <- need("area_basis_tables.rds"); cf <- need("centroid_fix_count.rds"); inv <- need("dat_inventory.rds"); ps <- need("pairing_study.rds")$R; di <- need("decision_impact.rds")
blk <- bind_rows(lapply(c(2000, 2010, 2020), function(v) need(sprintf("block_audit_%s.rds", v)))); fr <- bind_rows(lapply(c(2000, 2010, 2020), function(v) { f <- qa_out(sprintf("52c_%s.log", v)); if (!file.exists(f)) return(NULL); l <- grep("^[0-9:]+ +[0-9]{4} +[A-Z]{2} ", readLines(f), value = TRUE); if (!length(l)) return(NULL)
  m <- do.call(rbind, strsplit(trimws(gsub("  +", " ", l)), " ")); data.frame(vintage = as.integer(m[, 2]), state = m[, 3], pieces = as.integer(m[, 4]), frac_above_1 = as.integer(m[, 6]), frac_above_1_1e9 = as.integer(m[, 7]), max_frac = suppressWarnings(as.numeric(m[, 8])), na_pop_pieces = as.integer(m[, 9]), stringsAsFactors = FALSE) }))   # one line per state in the logs of 52c
bt <- blk %>% group_by(vintage) %>% summarise(blocks = sum(blocks), invalid = sum(invalid_blocks), multi = sum(blocks_in_more_than_one_zcta), extra = sum(extra_rows), dup_geoid = sum(duplicated_geoid_in_file), no_point = sum(no_internal_point), .groups = "drop")
ft <- fr %>% group_by(vintage) %>% summarise(pieces = sum(pieces), above1 = sum(frac_above_1), above1_tol = sum(frac_above_1_1e9), max_frac = max(max_frac, na.rm = TRUE), na_pieces = sum(na_pop_pieces), .groups = "drop")
log55 <- readLines(qa_out("55.log")); zero_pieces <- as.integer(sub(".*exact zero: ([0-9]+).*", "\\1", grep("exact zero", log55, value = TRUE)[1]))
for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f); n_tt <- nrow(tornado_tracks); era_pt <- au$point_by_era; zi <- au$zcta_invalid
row <- function(op, touches, allowed, nxt) paste0("| ", op, " | ", touches, " | ", allowed, " | ", nxt, " |")
rows <- c(
 row("SPC records before 1996 are not used", paste0(f0(au$yr_before_1996), " of ", f0(au$raw_rows), " rows of the SPC file"), "Yes: the package starts in 1996 (inherited from the original package; no reason is documented)", "kept"),
 row("SPC segment rows (`sg` = 2) and continuation rows (`sg` = -9) are not included", paste0(f0(sum(au$sg_table_1996[c("2", "-9")])), " rows from 1996 on (", f0(au$sg_table_1996[["2"]]), " segments, ", f0(au$sg_table_1996[["-9"]]), " continuation rows)"), "No: a source record is dropped", "the complete SPC record is shipped as its own dataset"),
 row("SPC columns are not included", paste0(length(au$cols_dropped), " of ", length(au$raw_cols), " columns (", paste0("`", au$cols_dropped, "`", collapse = ", "), ")"), "No: source values are dropped", "shipped in the complete SPC record"),
 row("SPC records without a valid start are dropped", paste0(f0(au$no_valid_start), " records"), "No (nothing is dropped now)", "stop and report instead"),
 row("Identifiers shared by two tornadoes are renamed `_1`, `_2`", paste0(f0(au$dup_id_rows), " records (", paste(au$dup_id_values, collapse = ", "), ")"), "Yes: an identifier, not a source value", "kept; the raw `om` stays in the complete SPC record"),
 row("Loss in millions of dollars (before 2007) is converted to dollars with `round(loss * 1e6)`", paste0(f0(au$loss_millions_n), " values; ", f0(au$loss_round_changed), " changed by the rounding (largest difference ", format(au$loss_round_max_diff_dollars, digits = 2), " dollars; at most three decimals in millions: ", paste(names(au$loss_millions_decimals), au$loss_millions_decimals, sep = ": ", collapse = "; "), " values with 0, 1, 2, 3 decimals)"), "Yes: an exact conversion, and the raw value is kept in `loss_raw`", "kept, exact conversion without rounding"),
 row("A loss of 0 becomes `NA` in `property_loss_tornado_total`", paste0(f0(sum(is.na(tornado_tracks$property_loss_tornado_total))), " tornadoes"), "Yes: the raw value is kept in `loss_raw`", "kept"),
 row("A width of 0 is replaced by 10 yards", paste0(f0(au$width_imputed), " tornadoes (", f0(au$width_imputed_by_type["line", "TRUE"]), " line tracks, ", f0(au$width_imputed_by_type["point", "TRUE"]), " point tracks; all from 1996 to 2006; the raw value was 0 in all of them and is not kept)"), "No: a source value is replaced", "removed: the width stays as SPC gives it"),
 row("A tornado with no usable end point (end coordinates 0 or missing, or equal to the start) is drawn as a disc", paste0(f0(au$point_total), " tornadoes (", pc(au$point_total / n_tt), "): ", f0(au$point_by_type[["point_equal_area"]]), " equal-area discs, ", f0(au$point_by_type[["point_half_width"]]), " half-width discs; ", f0(au$point_by_era["1996-2006", "TRUE"]), " from 1996 to 2006 and ", f0(au$point_by_era["2007+", "TRUE"]), " from 2007 on; ", f0(au$point_reason[["end equals start"]]), " have an end equal to the start and ", f0(au$point_reason[["end 0"]]), " an end of 0; the raw end coordinates are not stored)"), "No: geometry that is not in the source is invented", "removed: placed at the start point, no shape modeled, raw coordinates kept"),
 row("The modeled path is a straight line from SPC's start to SPC's end, buffered by half of SPC's single width with flat ends", paste0(f0(sum(tornado_tracks$track_type == "line")), " tornadoes"), "A model, not a source geometry: it is not a damage boundary", "kept for tornadoes with a start, an end and a width"),
 row("Coordinates are transformed to EPSG:5070 for areas and distances, and to EPSG:4269 for block points", "every geometry", "Yes: coordinate transformation", "kept"),
 row("Polygons repaired with `st_make_valid()`: ZCTA boundaries (as read, and after the transformation)", paste0("2000 file: ", f0(zi[[1]][["invalid_after_5070"]]), " of ", f0(zi[[1]][["features"]]), "; 2010 file: ", f0(zi[[2]][["invalid_after_5070"]]), " of ", f0(zi[[2]][["features"]]), "; 2020 file: ", f0(zi[[3]][["invalid_after_5070"]]), " of ", f0(zi[[3]][["features"]])), "Yes: repair of invalid geometry", "kept; the number repaired is reported"),
