 row("`area_prop_affected` is capped at 1 (intersection with the ZCTA polygon divided by `ALAND`)", paste0(f0(au$cap_modeled_rows_eq1), " of ", f0(au$cap_modeled_rows_total), " rows of `tornado_exposure` (", paste(names(au$cap_modeled_by_type), au$cap_modeled_by_type, collapse = ", "), ") and ", f0(au$cap_survey_rows_eq1), " row of `survey_exposure`; the uncapped ratio is above 1 in ", f0(nrow(ab$above1)), " rows, at most ", sprintf("%.3f", max(ab$above1$land))), "No: a source-derived value is capped and the uncapped value discarded", "removed: the uncapped ratio is shipped with `intersection_m2` and the ZCTA areas"),
 row("`area_prop_affected` divides an intersection with the full ZCTA polygon (land and water) by `ALAND` (land only)", paste0("all rows; against the full polygon the ratio differs by more than 1% in ", f0(ab$relative_difference_rows[["over_1pct"]]), " rows, by more than 10% in ", f0(ab$relative_difference_rows[["over_10pct"]]), " and by more than 50% in ", f0(ab$relative_difference_rows[["over_50pct"]])), "A basis mismatch, not a change of a source value", "documented; both areas are shipped (see the area basis below)"),
 row("`zcta_centroids`: longitude and latitude are rounded to 5 decimals", paste0(f0(au$centroid_rows), " rows"), "No: coordinates are rounded", "removed"),
 row("`zcta_centroids`: the geometric centroid of a ZCTA with no residents is replaced by a point on the polygon surface when it falls outside the polygon", paste0(f0(sum(cf$geometric_centroid_outside_polygon_replaced)), " of ", f0(sum(cf$zero_resident_zctas)), " ZCTA-years with no residents (", paste(cf$vintage, f0(cf$geometric_centroid_outside_polygon_replaced), sep = ": ", collapse = "; "), ")"), "A rule for a derived value, listed", "kept and listed"),
 row("Population: a block with an `NA` population is counted as 0", paste0(f0(sum(readRDS(qa_out("population_results.rds"))$summary$pop_na)), " blocks with an `NA` population in the three census years"), "No: a missing value is replaced", "stop and report instead"),
 row("Population: the share of a block inside a path is capped at 1", paste0(f0(sum(ft$pieces)), " path-block pieces recomputed for the modeled paths in ", nrow(fr), " of ", 52 * 3, " state-census year files (", paste(unique(fr$vintage), table(fr$vintage)[as.character(unique(fr$vintage))], sep = ": ", collapse = "; "), " states); ", f0(sum(ft$above1)), " above 1 (", f0(sum(ft$above1_tol)), " above 1 by more than 1e-9); largest share ", sprintf("%.12f", max(ft$max_frac))), "No: a value is capped", "removed: stop if a share exceeds 1 beyond floating-point tolerance"),
 row("Population: a block whose internal point lies in more than one ZCTA keeps only its first ZCTA (`!duplicated(GEOID)`)", paste0(f0(sum(bt$multi)), " blocks (", f0(sum(bt$extra)), " rows dropped) in ", paste(bt$vintage, f0(bt$multi), sep = ": ", collapse = "; "), "; blocks with a repeated GEOID in the block file: ", f0(sum(bt$dup_geoid)), "; blocks without an internal point: ", f0(sum(bt$no_point))), "No: rows are dropped", "removed: stop on a duplicated GEOID"),
 row("Survey: damage features with no `stormdate` are not fetched (the fetch filters on date)", paste0("lines ", f0(inv$null_stormdate[["lines"]]), ", polygons ", f0(inv$null_stormdate[["polygons"]]), ", points ", f0(inv$null_stormdate[["points"]])), "No: source features are dropped", "all features are fetched"),
 row("Survey: only some fields of the lines and polygons are fetched; the damage points are not used", paste0("lines: 11 of ", nrow(inv$fields[[2]]), " fields; polygons: 5 of ", nrow(inv$fields[[3]]), " fields; points: none of ", f0(inv$counts_all[["points"]]), " points"), "No: source values are dropped", "all fields of all layers are fetched"),
 row("Survey: damage polygons are fetched generalized by the service to 0.0002 degrees (`maxAllowableOffset`)", paste0(f0(au$dat_polys), " polygons, ", f0(au$dat_poly_vertices), " vertices; the swaths and `survey_exposure` are computed from them"), "No: geometry is generalized", "removed: polygons fetched at full resolution and stored unmodified"),
 row("Survey: exact copies of a survey line are merged", paste0(f0(au$exact_copy_lines_removed), " lines (", f0(au$dat_lines), " to ", f0(au$lines_after_merge), "); all object ids are kept in `survey_line_ids`"), "Yes: merging identical features", "kept or removed with the pairing rule"),
 row("Survey: for a multipart survey line only the longest part is used in the pairing distance", paste0(f0(au$multipart_lines_raw), " lines are multipart"), "No (not triggered)", "removed"),
 row("Survey: polygons are filtered before they are merged into a swath (rated EF0 to EF5; at least 90% of the area within the SPC width plus 500 m)", paste0(f0(au$swath_polygon_incidences_raw), " polygon-line crossings in ", f0(au$swath_pairs), " pairs; ", f0(au$swath_dropped_unrated_or_other_efscale), " dropped as not rated EF0 to EF5, ", f0(au$swath_dropped_by_90pct_rule), " dropped by the 90% rule, ", f0(au$swath_incidences_kept), " kept; ", f0(au$polygons_never_used), " of ", f0(au$dat_polys), " polygons are in no swath; ", f0(au$polygons_efscale_not_ef0_5), " polygons have an `efscale` other than EF0 to EF5"), "No: source polygons are dropped", "all polygons are shipped (`survey_zones`) with their rating"),
 row("Survey: the kept polygons of a pair are merged into one swath, so each zone's rating is lost", paste0(f0(au$usable_swaths), " swaths (", f0(au$polygons_used_distinct), " distinct polygons)"), "Merging is allowed; discarding the rating is not", "ratings are kept in `survey_zones`"),
 row("Survey: the swaths in `survey_tracks` are simplified to 50 m (`st_simplify`)", paste0(f0(au$survey_tracks_n), " swaths; ", f0(au$swath_vertices_full), " vertices before and ", f0(au$survey_tracks_vertices), " after; the area changes by a median of ", sprintf("%.1f", au$survey_tracks_area_change_pct[["50%"]]), "%, 90th percentile ", sprintf("%.1f", au$survey_tracks_area_change_pct[["90%"]]), "%, largest ", sprintf("%.1f", au$survey_tracks_area_change_pct[["100%"]]), "%"), "No: geometry is simplified", "removed"),
 row("Survey: a soft hyphen (U+00AD) is removed from one event id", "1 id", "No: a source string is changed", "kept raw"),
 row("Maps use generalized cartographic boundaries (`cb = TRUE`) while exposure uses the full TIGER/Line boundaries", "every map", "No: generalized geometry", "removed: maps use the same boundary files as the exposure calculation"))
pa <- need("survey_path_accuracy.rds"); cal <- pa$calibration; cal$cls <- cut(cal$chord_mi, c(-Inf, 5, 20, Inf), labels = c("under 5 miles", "5 to 20 miles", "over 20 miles")); ar <- pa$area_ratio; ratio <- tornado_tracks$tornado_area_m2[match(ar$tornado_id, tornado_tracks$tornado_id)] / (ar$swath_km2 * 1e6)
cls_txt <- paste(vapply(levels(cal$cls), function(l) { d <- cal$max_km[cal$cls == l]; paste0(l, " (", f0(length(d)), " tornadoes): median ", sprintf("%.2f", median(d)), " km, 90th percentile ", sprintf("%.2f", quantile(d, .9)), " km") }, ""), collapse = "; ")
acc <- paste0("**The modeled path is not a damage boundary at fine scales.** A modeled path is a straight line from SPC's start to SPC's end, drawn at SPC's single width. It does not follow the curve of a real path or its changing width, so it is not a damage boundary at scales finer than a kilometer. For the ", f0(nrow(cal)), " line tracks with a surveyed swath, the largest distance between the surveyed centerline and the modeled line has a median of ", sprintf("%.2f", median(cal$max_km)), " km and a 90th percentile of ", sprintf("%.2f", quantile(cal$max_km, .9)), " km; by straight-line length: ", cls_txt, ". The modeled path area is a median of ", sprintf("%.2f", median(ratio)), " times the surveyed swath area (10th to 90th percentile ", sprintf("%.2f", quantile(ratio, .1)), " to ", sprintf("%.2f", quantile(ratio, .9)), "; ", f0(nrow(ar)), " tornadoes with a usable swath). For pixel-scale work use the NWS damage polygons.")
rw <- ab$ratio_by_water; te <- ab$threshold_effect; pz <- ab$poly_vs_aland_zcta
basis <- paste0("**Area basis.** `area_prop_affected` is the area of the path inside the ZCTA polygon divided by the ZCTA's land area (`ALAND`). The Census Bureau's ZCTA polygons include water, so the numerator can include water while the denominator does not. The polygon area is a median of ", paste(sprintf("%.2f", pz$median_polygon_over_ALAND), collapse = ", "), " times `ALAND` in the 2000, 2010 and 2020 files (largest ", paste(sprintf("%.1f", pz$max), collapse = ", "), "; ZCTAs with more than 10% water: ", paste(f0(pz$zctas_with_water_over_10pct), collapse = ", "), "). Against the area of the full polygon (the same geometry as the numerator, which cannot exceed 1), the published value differs by more than 1% in ", f0(ab$relative_difference_rows[["over_1pct"]]), " of ", f0(ab$rows), " rows, by more than 10% in ", f0(ab$relative_difference_rows[["over_10pct"]]), " and by more than 50% in ", f0(ab$relative_difference_rows[["over_50pct"]]),
 ". In rows of ZCTAs with more than half of their area in water (", f0(rw$rows[rw$water_class == "over 50%"]), " rows) the land-based share is a median of ", sprintf("%.2f", rw$median_land_over_full[rw$water_class == "over 50%"]), " times the polygon-based share (largest ", sprintf("%.1f", rw$max[rw$water_class == "over 50%"]), "). The land basis is above 1 in ", f0(nrow(ab$above1)), " rows (largest ", sprintf("%.3f", max(ab$above1$land)), "), which is what the cap touched. With `area_thresh` of ", paste(te$area_thresh, collapse = ", "), " (example values, not recommendations) the land basis returns ", paste(f0(te$rows_land_basis), collapse = ", "), " rows and the polygon basis ", paste(f0(te$rows_full_basis), collapse = ", "), ". No land-only geometry is available to intersect with, so a land-only share cannot be computed exactly; the next version ships `intersection_m2`, `zcta_land_area_m2` and the polygon area, so a share can be computed on either basis.")
txt <- c("<!-- fidelity:start -->", "## What is and is not done to the source data", "",
 "The aim of the package is the highest quality of data on tornadoes, changed as little as possible. Allowed operations on source geometry are a coordinate transformation (projection), merging polygons and repairing invalid geometry, and each is listed below with how many features it touched. Any other change to a source geometry or value (simplifying, generalizing, rounding, snapping, thinning, truncating, capping, imputing, replacing or dropping) is not allowed. Where a transformation is needed, the raw value is kept in its own column.", "",
 "This is every operation applied to source data or geometry in the published version, with the number of records or features it touches. The last column says what the next version does.", "",
 "| Operation | What it touches | Allowed | Next version |", "|---|---|---|---|", rows, "", acc, "", basis, "",
 "<!-- fidelity:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- fidelity:start -->", kl, fixed = TRUE); b <- grep("<!-- fidelity:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("^## Property loss", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
